from research_helpers import source, decision, write_batch

refs = [
 ('megazone-eden','Megazone 23 Part III','Wikipedia contributors via indexed copy','https://levantado.ddns.net/ipfs/QmXoypizjW3WknFiJnKLwHCnL72vedxjQkDDP1mXWo6uco/wiki/Megazone_23.html','The System builds and supervises Eden; Eiji begins a network-security job.','Part III is a later Earth period, not the first shipboard Tokyo setting. Computer supervision does not settle household rights.'),
 ('moonrace','List of Turn A Gundam episodes','Wikipedia contributors','https://en.wikipedia.org/wiki/List_of_Turn_A_Gundam_episodes','Dianna ends a hibernation program and Moonrace people awaken.','Sleeping time is not active leisure or evidence of an awake population’s automatic welfare.'),
 ('veda-esf','Earth Sphere Federation','Gundam 00 Wiki contributors','https://gundam00.fandom.com/wiki/Earth_Sphere_Federation','Energy infrastructure and improved member-state living standards coexist with dictatorship and excluded poverty.','Power generation and Veda’s information control are not a complete material-access constitution.'),
 ('photon-energy','Photon Battery','Gundam Wiki contributors','https://gundam.fandom.com/wiki/Photon_Battery','Venus Globe manufactures batteries and Capital Tower regulates their distribution; some supplies are freely distributed to Towasanga.','An energy flow is not necessarily a free universal floor of food, shelter and care. A Venus Globe direct open returned 402 and was respected.'),
 ('casshan','Casshan','Wikipedia contributors','https://en.wikipedia.org/wiki/Casshan','Service automatons rebel, while a human-derived android fights them.','The original series differs from the 1993 OVA, Casshern Sins and the 2004 film; robotic bodies do not erase human-derived activity.'),
 ('casshern-sins','Casshern Sins','Wikipedia contributors','https://en.wikipedia.org/wiki/Casshern_Sins','Ruin affects robots and Luna selectively heals people/robots.','Immortality or a selected cure is not a general autonomous material-production constitution; unlike the original, this has its own world.'),
 ('casshern-film','Casshern 2004','Melbourne International Film Festival archive','https://miff.com.au/festival-archive/films/11962/casshern','An industrial military state and regenerative research produce neo-sapiens amid war.','The film’s military and biological mutation premise does not establish a civilian post-work economy.'),
 ('construction-cancel','Neo Tokyo: Construction Cancellation Order','Wikipedia contributors via indexed mirror','https://browse.zim.carpocratian.org/content/wikipedia_en_all_maxi_2022-05/A/Neo_Tokyo_%28film%29','An autonomous construction site continues its contract while a salaryman tries to stop it.','Only this segment is used. An unstoppable job site is not a durable supported resident society.'),
 ('yokohama','Yokohama Kaidashi Kikou','Wikipedia contributors','https://en.wikipedia.org/wiki/Yokohama_Kaidashi_Kikou','Alpha is a robot person running a café amid declining human society.','One working artificial person and a peaceful setting do not establish general post-work material access.'),
 ('aria','Aria','Wikipedia contributors','https://en.wikipedia.org/wiki/Aria_(manga)','Terraforming permits Aqua settlement; gondoliers and other people perform useful tourist work.','Paid human service and preserved old-world style are not proof of unnecessary jobs or a robot-supported welfare floor.')
]
S = [source('src-b71-'+sid,title,author,url,'screen_reference','Bounded public plot, character or episode passage read',claim,limitation) for sid,title,author,url,claim,limitation in refs]
rows = [
 ('c0545','needs_evidence','megazone-eden','Eden’s computer-supervised city does not establish ordinary access independent of useful human work.','Construction and network governance alone do not supply wages, entitlements or control over material production.'),
 ('c0546','needs_evidence','moonrace','Moonrace hibernation does not establish a post-work active population.','The short reference does not settle awake residents’ food/housing provision or participation.'),
 ('c0547','needs_evidence','veda-esf','Veda-directed politics and abundant energy do not establish a labor-independent civilian support floor.','Different ESF membership and political periods have different conditions; dictatorship is not an economic allocation mechanism.'),
 ('c0548','needs_evidence','photon-energy','Venus Globe’s advanced battery industry does not establish household access or a justified participation estimate.','An energy-producing civilization still needs its actual labor/property rules verified.'),
 ('c0549','needs_evidence','photon-energy','Capital Tower’s controlled energy distribution does not establish complete ordinary material provision.','Even free energy to one recipient does not imply free food, housing and care for all people.'),
 ('c0550','boundary_case','casshan','Robot rebellion and human submission do not establish a supported living human post-work order.','The original series’ conflict is not the separate restoration society in Sins.'),
 ('c0551','boundary_case','casshern-sins','Decaying artificial persons do not automatically constitute a post-work human economy.','Ruin and survival are real, but an applicable supported-person population and its production/access system are missing.'),
 ('c0552','needs_evidence','casshern-sins','Luna’s selective healing does not establish the restoration society’s wider material economy.','Treating bodies or granting longevity is not automatically technological replacement of production work or a universal support order.'),
 ('c0553','boundary_case','casshern-film','Industrial war, regeneration and neo-sapiens do not establish a post-work civilian distribution system.','Biological resurrection and military technology are not sufficient for admission.'),
 ('c0554','boundary_case','construction-cancel','The construction project is a workplace without an established supported resident population.','A temporarily endangered salaryman is not a durable post-work society, even though construction is fully automatic.'),
 ('c0555','needs_evidence','yokohama','Robot assistance and a peaceful decline do not establish general work-independent necessities.','A café operated by a robot person remains useful work and cannot stand for an entire population’s resource access.'),
 ('c0556','needs_evidence','aria','Aqua’s terraforming and tourism do not verify the discovery claim of a robot-supported human economy.','Human-guided gondolas provide valued real service; old-fashioned technology is not automatically employment-preserving make-work.')
]
D = [decision(cid,status,reason,['src-b71-'+sid],analysis=analysis,follow_up='Record the short gap/comparison and continue; do not reconstruct an entire franchise to rescue the lead.') for cid,status,sid,reason,analysis in rows]
write_batch(71,[f'c{i:04}' for i in range(545,557)],S,[],D,[
 'Twelve fast dispositions and ten scoped source records; no whole fiction or episode transcript read.',
 'Hibernation, energy abundance, body restoration and automatic construction are not interchangeable with a living population’s labor-independent material access.',
 'An Aria/Yokohama crossover fanfiction explicitly invented the desired robot economy; it was discarded rather than mistaken for canon. Gundam crossover/fanon and unrelated series references were likewise excluded.',
 'The original Casshan reference was checked separately to avoid importing a 1993 OVA or Sins premise.'
])
